D="/home/sulu/.claude/projects/-home-sulu-Neuefisch-wsl-ai-agent-project/0b72456d-e9be-4979-a036-7908604a857c.jsonl"
python3 - "$D" <<'PYEOF'
import json, sys, collections
path = sys.argv[1]
types = collections.Counter(); roles = collections.Counter(); sizes = collections.Counter()
sample = {}
with open(path) as f:
    for line in f:
        try: e = json.loads(line)
        except Exception: continue
        t = e.get("type", "?")
        types[t] += 1
        sizes[t] += len(line)
        m = e.get("message") or {}
        if isinstance(m, dict) and m.get("role"): roles[m["role"]] += 1
        if t not in sample: sample[t] = sorted(e.keys())
print("entry types (count, MB):")
for t, n in types.most_common():
    print(f"  {t:<24} {n:>4}   {sizes[t]/1e6:>6.2f} MB")
print("\nroles:", dict(roles))
print("\nkeys per type:")
for t, k in sample.items(): print(f"  {t}: {k}")
PYEOF
